function deepMergeSettings(target, source) {
  if (!source) return target;
  const result = Array.isArray(target) ? [...target] : { ...target };
  for (const key of Object.keys(source)) {
    if (source[key] !== null && typeof source[key] === 'object' && !Array.isArray(source[key])) {
      result[key] = deepMergeSettings(target[key] || {}, source[key]);
    } else if (source[key] !== undefined) {
      result[key] = source[key];
    }
  }

  // Ensure events array elements are deeply merged by matching id/type
  if (Array.isArray(target.events) && Array.isArray(result.events)) {
    result.events = target.events.map(defEv => {
      const srcEv = result.events.find(e => e.id === defEv.id || e.type === defEv.type);
      const merged = srcEv ? { ...defEv, ...srcEv } : { ...defEv };
      // Sanitize: If bride event mapUrl is empty or points to groom's Hoàng Gia Palace, or old unpinned road address, pin Nhà Văn hóa thôn Phú Nhiêu
      if (merged.type === 'bride' || merged.id === 'event-bride') {
        const brideMapPin = 'https://maps.app.goo.gl/dpLWJTZLtWg3DpmM7';
        let isLegacy = false;
        try {
          const dec = decodeURIComponent(merged.mapUrl || '');
          if (dec.includes('Thống Nhất') || dec.includes('ijkYsunZoUQ79kQbA') || dec.includes('20.762152677441485')) isLegacy = true;
        } catch(e) {}
        if ((merged.mapUrl || '').includes('Th%E1%BB%91ng') || (merged.mapUrl || '').includes('ijkYsunZoUQ79kQbA') || (merged.mapUrl || '').includes('20.762152677441485')) isLegacy = true;
        if (!merged.mapUrl || isLegacy) {
          merged.mapUrl = brideMapPin;
        }
      }
      // Sanitize: Ensure dateText uses standard concept
      if (merged.type === 'bride' || merged.id === 'event-bride') {
        if (!merged.dateText || merged.dateText.includes('/')) {
          merged.dateText = 'Thứ Bảy, 28 Tháng 11, 2026';
        }
      }
      if (merged.type === 'main' || merged.type === 'groom') {
        if (!merged.dateText || merged.dateText.includes('/')) {
          merged.dateText = 'Chủ Nhật, 29 Tháng 11, 2026';
        }
      }
      return merged;
    });
  }

  if (result.wedding) {
    if (!result.wedding.dateText || result.wedding.dateText.includes('/')) {
      result.wedding.dateText = 'Chủ Nhật, 29 Tháng 11, 2026';
    }
  }

  return result;
}

// Database helper functions
const WeddingDB = {
  getSettings() {
    try {
      const saved = localStorage.getItem(STORAGE_KEYS.SETTINGS);
      if (saved) {
        const parsed = JSON.parse(saved);
        return deepMergeSettings(DEFAULT_SETTINGS, parsed);
      }
    } catch (e) {
      console.warn('Error reading settings from localStorage:', e);
    }
    return JSON.parse(JSON.stringify(DEFAULT_SETTINGS));
  },

  saveSettings(settings) {
    try {
      localStorage.setItem(STORAGE_KEYS.SETTINGS, JSON.stringify(settings));
      if (typeof window !== 'undefined') {
        window.dispatchEvent(new CustomEvent('wedding_settings_updated', { detail: settings }));
        if (typeof window !== 'undefined' && window.weddingFirebaseDb) {
          try { window.weddingFirebaseDb.ref('settings').set(settings).catch(() => {}); } catch(e) {}
        }
        if (typeof fetch !== 'undefined') {
          fetch('/api/save-settings', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(settings)
          }).catch(() => {});
        }
      }
      return true;
    } catch (e) {
      console.error('Error saving settings:', e);
      return false;
    }
  },

  getGuests() {
    try {
      const saved = localStorage.getItem(STORAGE_KEYS.GUESTS);
      if (saved) {
        const parsed = JSON.parse(saved);
        if (Array.isArray(parsed)) {
          const filtered = parsed.filter(g => !['guest-1', 'guest-2', 'guest-3', 'guest-4'].includes(g.id));
          if (filtered.length !== parsed.length) {
            this.saveGuests(filtered);
          }
          return filtered;
        }
      }
    } catch (e) {
      console.warn('Error reading guests:', e);
    }
    return DEFAULT_GUESTS;
  },

  saveGuests(guests) {
    try {
      localStorage.setItem(STORAGE_KEYS.GUESTS, JSON.stringify(guests));
      if (typeof window !== 'undefined') {
        window.dispatchEvent(new CustomEvent('wedding_guests_synced', { detail: guests }));
        if (window.weddingFirebaseDb) {
          try {
            const map = {};
            guests.forEach(g => {
              if (g && g.id) map[g.id] = g;
            });
            window.weddingFirebaseDb.ref('guests').set(map).catch(() => {});
          } catch(e) {}
        }
      }
      return true;
    } catch (e) {
      console.error('Error saving guests:', e);
      return false;
    }
  },

  addGuest(guest) {
    const guests = this.getGuests();
    const newGuest = {
      id: 'guest-' + Date.now(),
      createdAt: new Date().toISOString().split('T')[0],
      status: 'pending',
      ...guest
    };
    guests.unshift(newGuest);
    this.saveGuests(guests);
    return newGuest;
  },

  updateGuest(id, updatedFields) {
    const guests = this.getGuests();
    const index = guests.findIndex(g => g.id === id);
    if (index !== -1) {
      guests[index] = { ...guests[index], ...updatedFields };
      this.saveGuests(guests);
      return guests[index];
    }
    return null;
  },

  deleteGuest(id) {
    const guests = this.getGuests().filter(g => g.id !== id);
    this.saveGuests(guests);
    return true;
  },

  getWishes() {
    try {
      const saved = localStorage.getItem(STORAGE_KEYS.WISHES);
      if (saved) {
        const parsed = JSON.parse(saved);
        if (Array.isArray(parsed)) {
          const filtered = parsed.filter(w => !['wish-0', 'wish-1', 'wish-2', 'wish-3'].includes(w.id));
          if (filtered.length !== parsed.length) {
            this.saveWishes(filtered);
          }
          return filtered;
        }
      }
    } catch (e) {
      console.warn('Error reading wishes:', e);
    }
    return DEFAULT_WISHES;
  },

  saveWishes(wishes) {
    try {
      localStorage.setItem(STORAGE_KEYS.WISHES, JSON.stringify(wishes));
      return true;
    } catch (e) {
      console.error('Error saving wishes:', e);
      return false;
    }
  },

  addWish(wish) {
    const wishes = this.getWishes();
    const now = new Date();
    const timeStr = `${now.getHours()}:${String(now.getMinutes()).padStart(2, '0')}:${String(now.getSeconds()).padStart(2, '0')} ${String(now.getDate()).padStart(2, '0')}/${String(now.getMonth() + 1).padStart(2, '0')}/${now.getFullYear()}`;
    const newWish = {
      id: 'wish-' + Date.now(),
      timestamp: timeStr,
      likes: 1,
      ...wish
    };
    wishes.unshift(newWish);
    this.saveWishes(wishes);

    if (typeof window !== 'undefined' && window.weddingFirebaseDb) {
      try {
        const ref = window.weddingFirebaseDb.ref('wishes').push();
        newWish.id = ref.key;
        ref.set({
          name: newWish.name,
          relation: newWish.relation || '',
          message: newWish.message || '',
          timestamp: newWish.timestamp,
          likes: newWish.likes || 1,
          createdAt: typeof firebase !== 'undefined' && firebase.database ? firebase.database.ServerValue.TIMESTAMP : Date.now()
        });
      } catch (e) {
        console.warn('Firebase push wish error:', e);
      }
    }

    return newWish;
  },

  getRSVPs() {
    try {
      const saved = localStorage.getItem(STORAGE_KEYS.RSVPS);
      if (saved) return JSON.parse(saved);
    } catch (e) {
      console.warn('Error reading RSVPs:', e);
    }
    return [];
  },

  addRSVP(rsvp) {
    const rsvps = this.getRSVPs();
    const now = new Date();
    const timeStr = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}-${String(now.getDate()).padStart(2, '0')} ${String(now.getHours()).padStart(2, '0')}:${String(now.getMinutes()).padStart(2, '0')}`;
    const newRSVP = {
      id: 'rsvp-' + Date.now(),
      submittedAt: timeStr,
      ...rsvp
    };
    rsvps.unshift(newRSVP);
    localStorage.setItem(STORAGE_KEYS.RSVPS, JSON.stringify(rsvps));

    if (typeof window !== 'undefined' && window.weddingFirebaseDb) {
      try {
        const ref = window.weddingFirebaseDb.ref('rsvps').push();
        newRSVP.id = ref.key;
        ref.set({
          name: newRSVP.name || '',
          phone: newRSVP.phone || '',
          attendance: newRSVP.attendance || 'yes',
          guestCount: newRSVP.guestCount || 1,
          party: newRSVP.party || 'Nhà Trai & Nhà Gái',
          wish: newRSVP.wish || '',
          submittedAt: newRSVP.submittedAt,
          createdAt: typeof firebase !== 'undefined' && firebase.database ? firebase.database.ServerValue.TIMESTAMP : Date.now()
        });
      } catch (e) {
        console.warn('Firebase push RSVP error:', e);
      }
    }

    // Also update guest status if matched by name or phone
    const guests = this.getGuests();
    const matched = guests.find(g => 
      (rsvp.name && g.name.toLowerCase() === rsvp.name.toLowerCase()) || 
      (rsvp.phone && g.phone === rsvp.phone)
    );
    if (matched) {
      this.updateGuest(matched.id, {
        status: rsvp.attendance === 'yes' ? 'attending' : 'declined',
        guestCount: rsvp.guestCount || 1,
        party: rsvp.party || 'event-main'
      });
    }

    return newRSVP;
  },

  getThemeId() {
    const urlParams = new URLSearchParams(window.location.search);
    if (urlParams.get('theme')) {
      return urlParams.get('theme');
    }
    const s = this.getSettings();
    return s.themeId || 'tender';
  },

  setThemeId(themeId) {
    const s = this.getSettings();
    s.themeId = themeId;
    this.saveSettings(s);
    return themeId;
  },

  getThemes() {
    return WEDDING_THEMES;
  },

  resetToDefault() {
    localStorage.removeItem(STORAGE_KEYS.SETTINGS);
    localStorage.removeItem(STORAGE_KEYS.GUESTS);
    localStorage.removeItem(STORAGE_KEYS.RSVPS);
    localStorage.removeItem(STORAGE_KEYS.WISHES);
    return true;
  },

  exportAllData() {
    return JSON.stringify({
      version: '1.0',
      exportedAt: new Date().toISOString(),
      settings: this.getSettings(),
      guests: this.getGuests(),
      rsvps: this.getRSVPs(),
      wishes: this.getWishes()
    }, null, 2);
  },

  importData(jsonString) {
    try {
      const data = JSON.parse(jsonString);
      if (data.settings) this.saveSettings(data.settings);
      if (data.guests) this.saveGuests(data.guests);
      if (data.wishes) this.saveWishes(data.wishes);
      if (data.rsvps) localStorage.setItem(STORAGE_KEYS.RSVPS, JSON.stringify(data.rsvps));
      return true;
    } catch (e) {
      console.error('Import failed:', e);
      return false;
    }
  }
};

// Export to window
if (typeof window !== 'undefined') {
  window.WeddingDB = WeddingDB;
  window.AI_WISH_SUGGESTIONS = AI_WISH_SUGGESTIONS;
}
